// Shared photo/painting gallery. Content and per-work choices live in data/.
function imagesForWork(work){const id=typeof work==='string'?work:work?.meta?.id;return (typeof poemImageMap==='undefined'?[]:poemImageMap[id]?.images||[]).map(item=>({...poemImageAssets[item.asset],...item})).filter(item=>item.src);}
function visualCredit(image){return `<a href="${escapeHtml(image.source)}" target="_blank" rel="noopener noreferrer">${escapeHtml(image.author)} · 原始来源 ↗</a> · <a href="${escapeHtml(image.licenseUrl)}" target="_blank" rel="noopener noreferrer">${escapeHtml(image.license==='Public domain'?'公版作品':image.license)}</a>`;}
function workImageGallery(work,compact=false){
 const images=imagesForWork(work);if(!images.length)return '';const id=work.meta.id;
 return `<section class="work-gallery ${compact?'compact-gallery':''}" aria-label="${escapeHtml(work.s[5])}配图"><div class="gallery-heading"><span>诗文画廊</span><small>${compact?'':'《'+escapeHtml(work.s[5])+'》 · '}${images.length}幅</small></div><div class="gallery-pictures">${images.map((item,index)=>`<figure class="gallery-item"><button data-gallery-work="${id}" data-gallery-index="${index}" aria-label="放大配图：${escapeHtml(item.title)}"><img src="${item.src}" alt="${escapeHtml(item.title)}；${escapeHtml(item.relation)}" loading="lazy" decoding="async" width="900" height="600" style="object-position:${item.objectPosition||'center'}"><span class="gallery-kind">${escapeHtml(item.type)} · ${escapeHtml(item.relation)}</span><span class="gallery-zoom">⤢</span></button><figcaption><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.note)}</p><small>${visualCredit(item)}</small></figcaption></figure>`).join('')}</div><p class="gallery-footnote">配图帮助观察与联想；现代照片、后世绘画都不等于诗人当时所见。点开可看原图与说明。</p></section>`;
}
function workImageCard(work){const image=imagesForWork(work)[0];return image?`<button class="poem-card-image" data-gallery-work="${work.meta.id}" data-gallery-index="0" aria-label="查看${escapeHtml(work.s[5])}的配图"><img src="${image.src}" alt="${escapeHtml(image.title)}" loading="lazy" decoding="async" width="600" height="340" style="object-position:${image.objectPosition||'center'}"><span>${escapeHtml(image.type)} · ${escapeHtml(image.relation)}</span></button>`:'';}
function bindWorkImages(){
 document.querySelectorAll('[data-gallery-work]').forEach(button=>button.onclick=()=>showWorkImage(button.dataset.galleryWork,+button.dataset.galleryIndex));
 document.querySelectorAll('.work-gallery img,.poem-card-image img').forEach(img=>img.onerror=()=>{img.hidden=true;const note=document.createElement('span');note.className='image-unavailable';note.textContent='图片暂未加载，可查看来源或切换下一幅';img.parentElement.append(note);});
}
function showWorkImage(id,index=0){
 const work=findReadingWork(id),images=imagesForWork(id);if(!work||!images.length)return;index=(index+images.length)%images.length;const item=images[index];
 showModal(`<div class="image-viewer"><p class="eyebrow">《${escapeHtml(work.s[5])}》 · 第${index+1}幅 / 共${images.length}幅</p><div class="image-viewer-head"><h2>${escapeHtml(item.title)}</h2><span>${escapeHtml(item.type)} · ${escapeHtml(item.relation)}</span></div><img class="gallery-full-image" src="${item.src}" alt="${escapeHtml(item.title)}完整构图"><div class="image-viewer-controls"><button id="previousWorkImage">← 上一幅</button><button id="returnToImageWork">回到原文</button><button id="nextWorkImage">下一幅 →</button></div><p class="image-relation-note">${escapeHtml(item.note)}</p><p>${item.artwork?'画作年代':'照片日期'}：${escapeHtml(item.date)} · ${visualCredit(item)}</p><p class="gallery-footnote">列表中的图片为裁切预览，此处保留完整构图。古画可能晚于诗作创作年代，不能作为当时建筑、地貌或事件的直接证据。</p></div>`);
 $('previousWorkImage').onclick=()=>showWorkImage(id,index-1);$('nextWorkImage').onclick=()=>showWorkImage(id,index+1);$('returnToImageWork').onclick=()=>readWork(id);
 const img=document.querySelector('.gallery-full-image');if(img)img.onerror=()=>{img.hidden=true;img.insertAdjacentHTML('afterend','<p class="image-unavailable">图片暂未加载，请切换下一幅，或打开原始来源。</p>');};
}
